                                                                                                                                                                                                    
  CREATE TABLE "FND_FAB"                                                                                                                                                                 
   (	"FAB_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 2 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                         
	"CREATION_DATE" DATE NOT NULL ENABLE,                                                                                                                                                              
	"UPDATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                         
	"UPDATE_DATE" DATE NOT NULL ENABLE,                                                                                                                                                                
	"REMARK" NVARCHAR2(512),                                                                                                                                                                           
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                       
	"NAME" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                              
	"IS_ENABLE" NUMBER NOT NULL ENABLE,                                                                                                                                                                
	"TENANT_ID" NUMBER(20,0) DEFAULT 3,                                                                                                                                                                
	"MANAGE_EXT_ORG_ID" NUMBER,                                                                                                                                                                        
	"ORG_GROUP_CODE" VARCHAR2(100),                                                                                                                                                                    
	"SYSTEM_CODE" NVARCHAR2(32),                                                                                                                                                                       
	"BASE_ID" NUMBER(20,0),                                                                                                                                                                            
	"WORK_STATION_IMAGE_URL" NVARCHAR2(255),                                                                                                                                                           
	"IS_WORK_STATION_ENABLE" NUMBER(*,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                    
	"IMAGE_WIDTH" NUMBER,                                                                                                                                                                              
	"IMAGE_HEIGHT" NUMBER,                                                                                                                                                                             
	"SCREEN_BACKGROUND_IMAGE_URL" NVARCHAR2(255) DEFAULT null,                                                                                                                                         
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                      
	 PRIMARY KEY ("FAB_ID")                                                                                                                                                                            
  USING INDEX  ENABLE,                                                                                                                                                                              
	 CHECK ( IS_WORK_STATION_ENABLE in (0, 1)) ENABLE,                                                                                                                                                 
	 CONSTRAINT "FND_ID_OPTIONAL_VALUES" CHECK ( FAB_ID >0) ENABLE                                                                                                                                     
   ) ;                                                                                                                                                                                              

